<?php
declare(strict_types=1);require_once __DIR__.'/../business/config/public_store_step23.php';$error=null;$catalog=[];try{$pdo=ps23_db();ps23_ensure($pdo);$ctx=ps23_context($pdo);$rows=ps23_catalog($pdo,$ctx['organization_id']);foreach($rows as$r)$catalog[(int)$r['id']]=['id'=>(int)$r['id'],'sku'=>$r['sku'],'name'=>$r['product_name'],'mrp'=>(float)$r['mrp'],'vp'=>(float)$r['volume_points'],'availability'=>$r['availability_status']];}catch(Throwable $e){$error=$e->getMessage();}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cart - Healthcare Wellness Club</title><link rel="stylesheet" href="store.css"></head><body><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Your Product Cart</small></span></a><div class="store-actions"><a class="store-btn" href="index.php">Continue Shopping</a><a class="store-btn primary" href="checkout.php">Checkout</a></div></div></header><main class="store-shell"><section class="store-hero"><div class="store-kicker">ORDER REQUEST CART</div><h1>Review products before sending your request.</h1><p>Cart totals shown here use current source-listed MRP. The server recalculates every line again during checkout.</p></section><?php if($error):?><div class="notice bad"><?=ps23_h($error)?></div><?php endif;?><section class="two-col" style="margin-top:16px"><article class="card"><h2>Products</h2><div id="cartRows"></div></article><aside class="card"><h2>Summary</h2><div class="summary-line"><span>MRP Total</span><strong id="sumMrp">₹0.00</strong></div><div class="summary-line"><span>Total VP</span><strong id="sumVp">0</strong></div><div class="notice">Delivery charge is calculated at checkout based on delivery mode and the source-listed VP rule. Taxes are not calculated here.</div><a class="store-btn primary" style="width:100%" href="checkout.php">Continue to Checkout</a><button class="store-btn" style="width:100%;margin-top:8px" id="clearCart">Clear Cart</button></aside></section></main><footer class="store-footer">No payment is collected at cart stage.</footer><script src="store.js"></script><script>const catalog=<?=json_encode($catalog,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;function money(v){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(v)}function render(){const cart=hwcCart();const box=document.getElementById('cartRows');box.innerHTML='';let mrp=0,vp=0;if(!cart.length){box.innerHTML='<div class="empty">Your cart is empty. <a href="index.php">Browse products</a></div>';}cart.forEach(row=>{const p=catalog[Number(row.product_id)];if(!p)return;const qty=Math.max(1,Math.min(20,Number(row.qty)||1));mrp+=p.mrp*qty;vp+=p.vp*qty;const div=document.createElement('div');div.className='cart-row';div.innerHTML=`<div><b>${escapeHtml(p.name)}</b><div class="meta">Stock ${escapeHtml(p.sku)} • ${p.availability==='unavailable'?'Unavailable':'MRP '+money(p.mrp)}</div></div><input class="store-input" type="number" min="1" max="20" value="${qty}" data-q="${p.id}"><strong>${money(p.mrp*qty)}</strong><button class="store-btn" data-r="${p.id}">×</button>`;box.appendChild(div)});document.getElementById('sumMrp').textContent=money(mrp);document.getElementById('sumVp').textContent=vp.toFixed(3).replace(/0+$/,'').replace(/\.$/,'');box.querySelectorAll('[data-q]').forEach(el=>el.addEventListener('change',()=>{hwcSet(el.dataset.q,el.value);render()}));box.querySelectorAll('[data-r]').forEach(el=>el.addEventListener('click',()=>{hwcRemove(el.dataset.r);render()}));hwcSyncCartBadge()}function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}document.getElementById('clearCart').addEventListener('click',()=>{hwcClear();render()});render();</script></body></html>